+shader_type spatial;
+// The towns' buildings (CosmosTown): one mesh a town, each piece's part of the
+// palette in its vertices (COLOR.r = the slot: walls, stone, columns, frescos,
+// trim...; COLOR.g = a little variation a piece) - the colours themselves are
+// these parameters: a town recoloured by setting them. Plaster mottled by a
+// little noise, grime near the ground.
+render_mode cull_back;
+
+uniform vec4 slot_color[12];
+uniform vec4 slot_look[12];   // x roughness, y metallic
+
+varying vec3 v_obj;
+
+float hash(vec3 p) {
+	return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
+}
+
+float vnoise(vec3 p) {
+	vec3 i = floor(p);
+	vec3 f = fract(p);
+	f = f * f * (3.0 - 2.0 * f);
+	float a = mix(mix(hash(i), hash(i + vec3(1, 0, 0)), f.x), mix(hash(i + vec3(0, 1, 0)), hash(i + vec3(1, 1, 0)), f.x), f.y);
+	float b = mix(mix(hash(i + vec3(0, 0, 1)), hash(i + vec3(1, 0, 1)), f.x), mix(hash(i + vec3(0, 1, 1)), hash(i + vec3(1, 1, 1)), f.x), f.y);
+	return mix(a, b, f.z);
+}
+
+void vertex() {
+	v_obj = VERTEX;
+}
+
+void fragment() {
+	int i = clamp(int(COLOR.r * 255.0 + 0.5), 0, 11);
+	float n = vnoise(v_obj * 0.9) * 0.55 + vnoise(v_obj * 4.3) * 0.3 + vnoise(v_obj * 19.0) * 0.15;
+	vec3 c = slot_color[i].rgb * (0.86 + 0.24 * n) * (0.93 + 0.14 * COLOR.g);
+	c *= mix(0.72, 1.0, smoothstep(0.0, 1.6, v_obj.y));   // (grime splashed up from the ground)
+	ALBEDO = c;
+	ROUGHNESS = clamp(slot_look[i].x + (n - 0.5) * 0.15, 0.05, 1.0);
+	METALLIC = slot_look[i].y;
+}

